package cn.mop.api;

import cn.mop.domain.DomainException;
import cn.mop.domain.inspection.*;
import cn.mop.domain.inspection.InspectionTemplate.Item;
import cn.mop.domain.inspection.InspectionWorksheet.*;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

/** Pure immutable provenance only. No database capture, approved quarter, report totals or publication claim. */
class InspectionSourceManifestTest {
    UUID id(int n){return UUID.fromString("7b000000-0000-4000-8000-"+String.format("%012x",n));}
    final Instant time=Instant.parse("2026-10-04T00:00:00Z");
    InspectionWorksheetContent content(){var template=new InspectionTemplate("router","合成",List.of(new Item("a","bc","d",null)));return new InspectionWorksheetContent(InspectionWorksheet.empty(id(1),id(3),"合成设备",InspectionTemplate.Snapshot.capture(id(1),id(4),1,template)),null);}
    InspectionSourceSnapshot source(){return source(id(2),1,"CREATE",content());}
    InspectionSourceSnapshot source(UUID worksheet,long version,String action,InspectionWorksheetContent content){return new InspectionSourceSnapshot(id(1),worksheet,version,id(5),time,id(5),time.plusMillis(version-1),action,action.equals("ARCHIVE"),content);}
    InspectionSourceManifest manifest(InspectionSourceSnapshot... values){return new InspectionSourceManifest(id(1),List.of(values));}
    InspectionWorksheetRepository.Entry entry(Instant updated){var s=source();return new InspectionWorksheetRepository.Entry(s.worksheetId().toString(),s.tenantId().toString(),s.createdBy().toString(),s.version(),s.createdAt(),updated,s.recordedBy().toString(),s.recordedAt(),s.action(),s.revisionArchived(),s.content());}
    @Test void independentPythonGoldenCoversFullTemplateContentAndRecordingMetadata(){assertEquals("15d9188e184636f537672c8638d31f1e5902e559d9ef0ba027d489b4bcab86b2",source().fingerprint());assertEquals(565,source().canonicalBytes().length);assertEquals("c53a70ad013720e659a90396a05911945656b6c382dd216d15ae98e91e1d8d38",manifest(source()).fingerprint());}
    @Test void templateEncodingExtractionKeepsExistingGoldenAndReturnsFreshBytes(){var template=content().worksheet().template().definition();assertEquals("561edb61f43839192aed9199ed87f49a3fc98554c3ed03360fdb5999fa48c2ad",template.fingerprint());var bytes=template.canonicalBytes();Arrays.fill(bytes,(byte)0);assertEquals("561edb61f43839192aed9199ed87f49a3fc98554c3ed03360fdb5999fa48c2ad",template.fingerprint());}
    @Test void inputOrderIsNotAnImplicitNewestOrWorstSelection(){var first=source();var second=source(id(9),1,"CREATE",content());assertEquals(manifest(first,second),manifest(second,first));assertEquals(manifest(first,second).fingerprint(),manifest(second,first).fingerprint());assertEquals(List.of(id(2),id(9)),manifest(second,first).sources().stream().map(InspectionSourceSnapshot::worksheetId).toList());}
    @Test void selectedDifferentRevisionsOfOneWorksheetRemainExplicitAmbiguities(){var one=source();var two=source(id(2),2,"UPDATE",content());var value=manifest(two,one);assertEquals(2,value.selectedSourceCount());assertEquals(1,value.distinctSelectedAssets());assertEquals(List.of(1L,2L),value.assetsWithMultipleSources().get(id(3)).stream().map(InspectionSourceSnapshot.Reference::version).toList());assertNull(value.quarterSelectionRule());}
    @Test void exactDuplicateRevisionCannotSilentlyCountTwice(){assertEquals(400,assertThrows(DomainException.class,()->manifest(source(),source())).status);}
    @Test void oldSourceObjectsAndManifestDoNotRecomputeAfterAnotherRevisionAppears(){var original=source();var value=manifest(original);String hash=value.fingerprint();var updated=content().worksheet().record("a",new Observation(Result.REQUIRES_ACTION,"后来填写",List.of()));var next=source(id(2),2,"UPDATE",new InspectionWorksheetContent(updated,time));assertNotEquals(original.fingerprint(),next.fingerprint());assertEquals(hash,value.fingerprint());assertEquals(0,value.sources().get(0).content().worksheet().summary().answered());assertNull(value.sources().get(0).content().reportedPerformedAt());}
    @Test void returnedCollectionsAndDiagnosticMapsAreDeeplyUnmodifiable(){var input=new ArrayList<>(List.of(source(),source(id(9),1,"CREATE",content())));var value=new InspectionSourceManifest(id(1),input);input.clear();assertEquals(2,value.sources().size());assertThrows(UnsupportedOperationException.class,()->value.sources().clear());assertThrows(UnsupportedOperationException.class,()->value.assetsWithMultipleSources().clear());assertThrows(UnsupportedOperationException.class,()->value.assetsWithMultipleSources().get(id(3)).clear());assertThrows(UnsupportedOperationException.class,()->value.sourcesWithUnknownInspectionTime().clear());assertThrows(UnsupportedOperationException.class,()->value.sources().get(0).content().worksheet().template().definition().items().clear());}
    @Test void snapshotAndManifestReturnedByteArraysCannotAlterTheirStoredMeaning(){var s=source();var m=manifest(s);String a=s.fingerprint(),b=m.fingerprint();Arrays.fill(s.canonicalBytes(),(byte)0);Arrays.fill(m.canonicalBytes(),(byte)0);assertEquals(a,s.fingerprint());assertEquals(b,m.fingerprint());}
    @Test void emptySelectionIsNotZeroTenantAssetsOrACompletedReport(){var value=manifest();assertEquals(0,value.selectedSourceCount());assertEquals(0,value.distinctSelectedAssets());assertNull(value.tenantAssetPopulation());assertFalse(value.formalReportGeneratable());assertFalse(value.reportPublished());assertEquals("CONFIG_PENDING",value.generationStatus());}
    @Test void noBusinessTimezoneSelectionArchiveMetricOrReportTemplateDefaultsAreInvented(){var value=manifest(source());assertNull(value.periodTimeZone());assertNull(value.quarterSelectionRule());assertNull(value.archivedSourcePolicy());assertNull(value.metricVersion());assertNull(value.reportTemplateVersion());assertEquals(1,value.sourcesWithUnknownInspectionTime().size());assertEquals(1,value.incompletelyEnteredSources().size());assertEquals("SELF_REPORTED_UNVERIFIED",value.sources().get(0).verificationStatus());}
    @Test void explicitCompleteManualNormalAndKnownTimeStillDoNotAuthorizeReportGeneration(){var sheet=content().worksheet().record("a",new Observation(Result.NORMAL,null,List.of()));var known=source(id(2),1,"CREATE",new InspectionWorksheetContent(sheet,time));var value=manifest(known);assertTrue(value.sourcesWithUnknownInspectionTime().isEmpty());assertTrue(value.incompletelyEnteredSources().isEmpty());assertFalse(value.formalReportGeneratable());assertFalse(value.reportPublished());assertFalse(known.evidenceAccessGranted());}
    @Test void selectedArchiveRevisionRemainsVisibleWithoutChoosingInclusionPolicy(){var archived=source(id(2),2,"ARCHIVE",content());assertEquals(source().content().fingerprint(),archived.content().fingerprint());assertNotEquals(source().fingerprint(),archived.fingerprint());var value=manifest(source(),archived);assertEquals(1,value.archivedSelectedRevisions().size());assertEquals(2,value.assetsWithMultipleSources().get(id(3)).size());assertNull(value.archivedSourcePolicy());}
    @Test void tenantMismatchIs404AndCannotBecomeAnUnscopedReference(){assertEquals(404,assertThrows(DomainException.class,()->new InspectionSourceManifest(id(99),List.of(source()))).status);assertEquals(404,assertThrows(DomainException.class,()->new InspectionSourceSnapshot(id(99),id(2),1,id(5),time,id(5),time,"CREATE",false,content())).status);}
    @Test void invalidIdentityRevisionAndLifecycleFail(){for(long version:new long[]{0,9_007_199_254_740_991L})assertThrows(DomainException.class,()->source(id(2),version,"UPDATE",content()));assertThrows(DomainException.class,()->source(id(2),1,"UPDATE",content()));assertThrows(DomainException.class,()->source(id(2),2,"CREATE",content()));assertThrows(DomainException.class,()->new InspectionSourceSnapshot(id(1),null,1,id(5),time,id(5),time,"CREATE",false,content()));assertThrows(DomainException.class,()->new InspectionSourceSnapshot(id(1),id(2),2,id(5),time,id(5),time,"ARCHIVE",false,content()));assertThrows(DomainException.class,()->new InspectionSourceSnapshot(id(1),id(2),1,id(5),time,id(6),time,"CREATE",false,content()));}
    @Test void invalidTimesAndFutureSelfReportedTimeCannotHideBehindSourceMetadata(){for(Instant invalid:List.of(time.plusNanos(1),Instant.parse("0000-12-31T23:59:59.999Z"),Instant.parse("+10000-01-01T00:00:00Z")))assertThrows(DomainException.class,()->new InspectionSourceSnapshot(id(1),id(2),1,id(5),invalid,id(5),invalid,"CREATE",false,content()));assertThrows(DomainException.class,()->new InspectionSourceSnapshot(id(1),id(2),1,id(5),time,id(5),time.minusMillis(1),"CREATE",false,content()));assertThrows(DomainException.class,()->source(id(2),1,"CREATE",new InspectionWorksheetContent(content().worksheet(),time.plusMillis(1))));}
    @Test void metadataActorWorksheetVersionAndRecordTimeAreBoundSeparatelyFromContent(){var old=source();var changedActor=new InspectionSourceSnapshot(id(1),id(2),1,id(6),time,id(6),time,"CREATE",false,content());var changedTime=new InspectionSourceSnapshot(id(1),id(2),1,id(5),time,id(5),time.plusMillis(1),"CREATE",false,content());for(var value:List.of(changedActor,changedTime,source(id(9),1,"CREATE",content()),source(id(2),2,"UPDATE",content())))assertNotEquals(old.fingerprint(),value.fingerprint());}
    @Test void mutableHeadUpdateTimeDoesNotChangeASelectedHistoricalRevisionDigest(){assertEquals(source(),InspectionSourceSnapshot.fromEntry(entry(time)));assertEquals(source().fingerprint(),InspectionSourceSnapshot.fromEntry(entry(time.plusSeconds(3600))).fingerprint());assertThrows(DomainException.class,()->InspectionSourceSnapshot.fromEntry(entry(time.minusMillis(1))));assertThrows(DomainException.class,()->InspectionSourceSnapshot.fromEntry(null));}
    @Test void referencesBindBothRevisionMetadataAndWorksheetContentWithoutGrantingAccess(){var value=source();assertEquals(value.worksheetId(),value.reference().worksheetId());assertEquals(value.version(),value.reference().version());assertEquals(value.fingerprint(),value.reference().snapshotSha256());assertEquals(value.content().fingerprint(),value.reference().contentSha256());assertEquals("IMMUTABLE_INSPECTION_WORKSHEET_REVISION",value.sourceType());assertFalse(value.evidenceAccessGranted());}
    @Test void technicalSourceLimitRejectsRatherThanTruncatesAndNullsAreNotEmpty(){var sources=new ArrayList<InspectionSourceSnapshot>();for(int i=0;i<1000;i++)sources.add(source(id(100+i),1,"CREATE",content()));assertEquals(1000,new InspectionSourceManifest(id(1),sources).sources().size());sources.add(source(id(2000),1,"CREATE",content()));assertEquals(413,assertThrows(DomainException.class,()->new InspectionSourceManifest(id(1),sources)).status);assertThrows(DomainException.class,()->new InspectionSourceManifest(id(1),null));assertThrows(DomainException.class,()->new InspectionSourceManifest(id(1),Arrays.asList(source(),null)));}
    @Test void byteBudgetCountsFullTemplateEvenWhenNoAnswersHaveBeenEntered(){var items=new ArrayList<Item>();for(int i=0;i<100;i++)items.add(new Item("item_"+i,"组","项","😀".repeat(2000)));var template=new InspectionTemplate("custom","合成大模板",items);var value=new InspectionWorksheetContent(InspectionWorksheet.empty(id(1),id(3),"合成设备",InspectionTemplate.Snapshot.capture(id(1),id(4),1,template)),null);var first=source(id(2),1,"CREATE",value);assertTrue(first.canonicalBytes().length>800000);var values=new ArrayList<InspectionSourceSnapshot>();for(int i=0;i<22;i++)values.add(source(id(100+i),1,"CREATE",value));assertEquals(413,assertThrows(DomainException.class,()->new InspectionSourceManifest(id(1),values)).status);}
}
